import { cn } from '@/lib/utils'

type SlideFrom = 'bottom' | 'top' | 'left' | 'right'

interface SlideProps {
  in?: boolean
  from?: SlideFrom
  distance?: number
  children: React.ReactNode
  className?: string
}

function translateClass(from: SlideFrom, distance: number, visible: boolean): string {
  if (visible) return 'motion-safe:translate-x-0 motion-safe:translate-y-0'
  const px = `${distance}px`
  switch (from) {
    case 'bottom': return `motion-safe:translate-y-[${px}]`
    case 'top':    return `motion-safe:-translate-y-[${px}]`
    case 'right':  return `motion-safe:translate-x-[${px}]`
    case 'left':   return `motion-safe:-translate-x-[${px}]`
  }
}

/**
 * CSS transform + opacity slide. Transforms are gated with motion-safe: prefix
 * so reduced-motion users only get the opacity fade.
 */
export function Slide({
  in: visible = true,
  from = 'bottom',
  distance = 8,
  children,
  className,
}: SlideProps) {
  return (
    <div
      className={cn(
        'motion-safe-fade transition-[opacity,transform]',
        visible ? 'opacity-100' : 'opacity-0',
        translateClass(from, distance, visible),
        className,
      )}
      style={{
        transitionDuration: 'var(--duration-base)',
        transitionTimingFunction: 'var(--ease-standard)',
      }}
    >
      {children}
    </div>
  )
}

