type SlideFrom = 'bottom' | 'top' | 'left' | 'right'

interface SlideProps {
  in?: boolean
  from?: SlideFrom
  distance?: number
  children: React.ReactNode
  className?: string
}

/**
 * Returns the hidden-state transform value for a given direction + distance.
 * Uses inline style (not Tailwind bracket classes) so the transform is never
 * dropped by JIT. Tailwind only handles the transition-timing/duration.
 *
 * Reduced-motion: the global @media rule sets transition-duration to 0.01ms
 * which collapses the transform to instant — only the .motion-safe-fade
 * opacity fade survives, which is the correct behavior.
 */
function hiddenTransform(from: SlideFrom, distance: number): string {
  switch (from) {
    case 'bottom': return `translate3d(0, ${distance}px, 0)`
    case 'top':    return `translate3d(0, -${distance}px, 0)`
    case 'right':  return `translate3d(${distance}px, 0, 0)`
    case 'left':   return `translate3d(-${distance}px, 0, 0)`
  }
}

/**
 * CSS transform + opacity slide. Transforms applied via inline style so
 * Tailwind JIT never strips them. Reduced-motion users get opacity-only.
 */
export function Slide({
  in: visible = true,
  from = 'bottom',
  distance = 8,
  children,
  className,
}: SlideProps) {
  return (
    <div
      className={cn(
        'motion-safe-fade transition-[opacity,transform]',
        visible ? 'opacity-100' : 'opacity-0',
        className,
      )}
      style={{
        transform: visible ? 'translate3d(0, 0, 0)' : hiddenTransform(from, distance),
        transitionDuration: 'var(--duration-base)',
        transitionTimingFunction: 'var(--ease-standard)',
      }}
    >
      {children}
    </div>
  )
}

