import { useState } from 'react'

/**
 * Returns the value from the previous render.
 * On the first render, returns `undefined`.
 *
 * The "setState during render" pattern is intentional and safe here — React
 * detects that `current` changed, bails out of the re-render loop (because
 * after the first update, `value === current`), and no infinite loop occurs.
 * See: https://react.dev/reference/react/useState#storing-information-from-previous-renders
 */
export function usePrevious<T>(value: T): T | undefined {
  const [prev, setPrev] = useState<T | undefined>(undefined)
  const [current, setCurrent] = useState<T>(value)

  if (value !== current) {
    setPrev(current)
    setCurrent(value)
  }

  return prev
}

