import { Moon, Sun, SunMoon } from 'lucide-react'
import { useTheme } from 'next-themes'
import { Button } from '@/components/ui/button'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'

interface ThemeToggleProps {
  variant?: 'icon' | 'segmented'
  className?: string
}

export function ThemeToggle({ variant = 'icon', className }: ThemeToggleProps) {
  const { theme, resolvedTheme, setTheme } = useTheme()

  if (variant === 'segmented') {
    const options = [
      { value: 'light',  label: 'Light',  Icon: Sun    },
      { value: 'system', label: 'System', Icon: SunMoon },
      { value: 'dark',   label: 'Dark',   Icon: Moon   },
    ] as const
    return (
      <div
        role="group"
        aria-label="Color theme"
        className={cn(
          'inline-flex items-center rounded-lg border border-border bg-muted p-0.5',
          className,
        )}
      >
        {options.map(({ value, label, Icon }) => (
          <button
            key={value}
            type="button"
            onClick={() => setTheme(value)}
            aria-pressed={theme === value}
            className={cn(
              'flex h-8 cursor-pointer items-center gap-1.5 rounded-md px-3 text-[13px] font-medium text-muted-foreground transition-colors',
              theme === value && 'bg-background text-foreground shadow-[var(--shadow-soft)]',
            )}
          >
            <Icon className="h-3.5 w-3.5" aria-hidden="true" />
            {label}
          </button>
        ))}
      </div>
    )
  }

  // icon variant — h-9 w-9 for header use
  const isDark = resolvedTheme === 'dark'
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            variant="ghost"
            size="icon"
            className={cn('h-9 w-9', className)}
            onClick={() => setTheme(isDark ? 'light' : 'dark')}
            aria-label={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
          />
        }
      >
        {isDark
          ? <Sun className="h-4 w-4" aria-hidden="true" />
          : <Moon className="h-4 w-4" aria-hidden="true" />
        }
      </TooltipTrigger>
      <TooltipContent>
        {isDark ? 'Light mode (Cmd+Shift+L)' : 'Dark mode (Cmd+Shift+L)'}
      </TooltipContent>
    </Tooltip>
  )
}

